import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

// Define the container block for the mutator
Blockly.Blocks['exception_container'] = {
  init: function() {
    this.appendDummyInput()
        .appendField('Exceptions');
    this.appendStatementInput('STACK');
    this.setColour(230);
    this.setTooltip('Add, remove, or reorder exceptions');
    this.contextMenu = false;
  }
};

// Define the individual exception item block for the mutator
Blockly.Blocks['exception_item'] = {
  init: function() {
    this.appendDummyInput()
        .appendField('Exception')
        .appendField(new Blockly.FieldTextInput('Exception'), 'EXCEPTION_TYPE');
    this.setPreviousStatement(true);
    this.setNextStatement(true);
    this.setColour(230);
    this.setTooltip('An exception handler');
    this.contextMenu = false;
  }
};

// Create a mixin for handling multiple exceptions
const ExceptionMixin = {
  exceptCount_: 1,

  saveExtraState: function() {
    return {
      'exceptCount': this.exceptCount_
    };
  },

  loadExtraState: function(state) {
    this.exceptCount_ = state['exceptCount'] || 1;
    this.updateShape_();
  },

  decompose: function(workspace) {
    const containerBlock = workspace.newBlock('exception_container');
    containerBlock.initSvg();

    let connection = containerBlock.getInput('STACK').connection;
    for (let i = 0; i < this.exceptCount_; i++) {
      const exceptionBlock = workspace.newBlock('exception_item');
      exceptionBlock.initSvg();
      connection.connect(exceptionBlock.previousConnection);
      connection = exceptionBlock.nextConnection;
    }

    return containerBlock;
  },

  compose: function(containerBlock) {
    let exceptionBlock = containerBlock.getInputTargetBlock('STACK');
    let connections = [];
    let exceptions = [];
    while (exceptionBlock) {
      connections.push(exceptionBlock.valueConnection_);
      exceptions.push(exceptionBlock.getFieldValue('EXCEPTION_TYPE'));
      exceptionBlock = exceptionBlock.nextConnection &&
          exceptionBlock.nextConnection.targetBlock();
    }

    this.exceptCount_ = connections.length;
    this.updateShape_();

    for (let i = 0; i < this.exceptCount_; i++) {
      if (connections[i]) {
        this.getInput('EXCEPT_' + i).connection.connect(connections[i]);
      }
      if (exceptions[i]) {
        this.setFieldValue(exceptions[i], 'EXCEPTION_' + i);
      }
    }
  },

  saveConnections: function(containerBlock) {
    let exceptionBlock = containerBlock.getInputTargetBlock('STACK');
    let i = 0;
    while (exceptionBlock) {
      const input = this.getInput('EXCEPT_' + i);
      exceptionBlock.valueConnection_ = input && input.connection.targetConnection;
      i++;
      exceptionBlock = exceptionBlock.nextConnection &&
          exceptionBlock.nextConnection.targetBlock();
    }
  },

  updateShape_: function() {
    for (let i = 0; i < this.exceptCount_; i++) {
      const input = this.getInput('EXCEPT_' + i);
      if (input) {
        this.removeInput('EXCEPT_' + i);
      }
    }

    for (let i = 0; i < this.exceptCount_; i++) {
      this.appendStatementInput('EXCEPT_' + i)
          .setCheck(null)
          .appendField('except')
          .appendField(new Blockly.FieldTextInput('Exception'), 'EXCEPTION_' + i);
    }
  }
};

// Define the try-except block
Blockly.Blocks['program_try_except'] = {
  init: function() {
    this.appendDummyInput()
        .appendField('Program Structure');
    this.appendStatementInput('TRY')
        .setCheck(null)
        .appendField('try');
    this.updateShape_();
    this.appendStatementInput('FINALLY')
        .setCheck(null)
        .appendField('finally');
    this.setColour(230);
    this.setTooltip('Main program structure with try-except-finally');
    this.setMutator(new Blockly.Mutator(['exception_item']));
  },
  ...ExceptionMixin
};

// Update the generator registration to use pythonGenerator
pythonGenerator.forBlock['program_try_except'] = function(block) {
  const tryCode = pythonGenerator.statementToCode(block, 'TRY') || '    pass\n';
  let exceptCode = '';
  for (let i = 0; i < block.exceptCount_; i++) {
    let exceptionType = block.getFieldValue('EXCEPTION_' + i);
    let exceptBody = pythonGenerator.statementToCode(block, 'EXCEPT_' + i) || '    pass\n';
    exceptCode += `except ${exceptionType}:\n${exceptBody}`;
  }
  const finallyCode = pythonGenerator.statementToCode(block, 'FINALLY') || '    pass\n';

  let code = 'try:\n' + tryCode;
  if (exceptCode.trim()) {
    code += exceptCode;
  }
  if (finallyCode.trim()) {
    code += 'finally:\n' + finallyCode;
  }
  
  return code;
};
